import'package:dierb_api_client/dierb_api_client.dart';import'package:flutter/material.dart';import'../authentication/login.dart';
class _Section{const _Section(this.label,this.icon,this.resource);final String label,resource;final IconData icon;}class HomeScreen extends StatefulWidget{const HomeScreen({super.key});@override State<HomeScreen>createState()=>_State();}class _State extends State<HomeScreen>{final api=DierbApi();int selected=0;Map<String,dynamic>?dashboard;List<dynamic>rows=const[];bool loading=true;String?error;static const sections=[_Section('لوحة التحكم',Icons.dashboard,'dashboard'),_Section('المستخدمون',Icons.people,'users'),_Section('التجار',Icons.badge,'merchants'),_Section('المتاجر',Icons.store,'stores'),_Section('المنتجات',Icons.inventory_2,'products'),_Section('الأقسام',Icons.category,'categories'),_Section('الطلبات',Icons.receipt_long,'orders'),_Section('المندوبون',Icons.delivery_dining,'riders'),_Section('اسأل ديرب',Icons.forum,'questions'),_Section('البلاغات',Icons.flag,'reports'),_Section('الإعدادات',Icons.settings,'settings')];@override void initState(){super.initState();load();}@override void dispose(){api.close();super.dispose();}Future<void>load()async{setState(()=>loading=true);try{if(selected==0)dashboard=await api.adminDashboard();else rows=await api.adminList(sections[selected].resource);if(mounted)setState((){loading=false;error=null;});}catch(e){if(mounted)setState((){loading=false;error=e is DierbApiException?e.message:'تعذر تحميل البيانات';});}}Future<void>logout()async{await api.logout();if(mounted)Navigator.pushAndRemoveUntil(context,MaterialPageRoute(builder:(_)=>const LoginScreen()),(_)=>false);}Future<void>action(String path,Map<String,dynamic>body)async{try{await api.adminPatch(path,body);await load();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e is DierbApiException?e.message:'تعذر تنفيذ الإجراء')));}}@override Widget build(BuildContext context){final narrow=MediaQuery.sizeOf(context).width<850;return Scaffold(appBar:AppBar(title:const Text('إدارة ديرب',style:TextStyle(fontWeight:FontWeight.w900)),actions:[IconButton(onPressed:logout,icon:const Icon(Icons.logout))]),drawer:narrow?Drawer(child:nav()):null,body:Row(children:[if(!narrow)SizedBox(width:240,child:nav()),Expanded(child:loading?const Center(child:CircularProgressIndicator()):error!=null?Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Text(error!),TextButton(onPressed:load,child:const Text('إعادة المحاولة'))])):selected==0?Dashboard(data:dashboard??{}):Panel(resource:sections[selected].resource,rows:rows,action:action))]));}Widget nav()=>ListView(children:List.generate(sections.length,(i)=>ListTile(selected:i==selected,leading:Icon(sections[i].icon),title:Text(sections[i].label),onTap:(){setState(()=>selected=i);if(Navigator.canPop(context))Navigator.pop(context);load();})));}
class Dashboard extends StatelessWidget{const Dashboard({super.key,required this.data});final Map<String,dynamic>data;@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(24),children:[const Text('نظرة عامة حقيقية',style:TextStyle(fontSize:26,fontWeight:FontWeight.w900)),const SizedBox(height:18),Wrap(spacing:12,runSpacing:12,children:data.entries.map((e)=>Container(width:220,padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(20)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(labels[e.key]??e.key),Text('${e.value}',style:const TextStyle(fontSize:28,fontWeight:FontWeight.w900))]))).toList())]);static const labels={'users':'المستخدمون','merchants':'التجار','stores':'المتاجر','products':'المنتجات','orders':'الطلبات','riders':'المندوبون','questions':'الأسئلة','openReports':'البلاغات المفتوحة'};}
class Panel extends StatelessWidget{const Panel({super.key,required this.resource,required this.rows,required this.action});final String resource;final List<dynamic>rows;final Future<void>Function(String,Map<String,dynamic>)action;@override Widget build(BuildContext context)=>rows.isEmpty?const Center(child:Text('لا توجد بيانات')):ListView.separated(padding:const EdgeInsets.all(20),itemCount:rows.length,separatorBuilder:(_,__)=>const SizedBox(height:8),itemBuilder:(_,i){final m=Map<String,dynamic>.from(rows[i]as Map),id=m['id']?.toString()??'',user=m['user']as Map?;final title=(m['name']??m['businessName']??m['title']??m['key']??user?['name']??m['orderNumber']??id).toString(),subtitle=(m['email']??user?['email']??m['status']??m['role']??'').toString();return Card(child:ListTile(title:Text(title,style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text(subtitle),trailing:menu(m,id)));});Widget?menu(Map<String,dynamic>m,String id){if(resource=='merchants'||resource=='riders')return PopupMenuButton<String>(onSelected:(v)=>action('$resource/$id/status',{'status':v}),itemBuilder:(_)=>const[PopupMenuItem(value:'approved',child:Text('موافقة')),PopupMenuItem(value:'rejected',child:Text('رفض')),PopupMenuItem(value:'suspended',child:Text('إيقاف'))]);if(resource=='questions')return PopupMenuButton<String>(onSelected:(v)=>action('questions/$id/status',{'status':v}),itemBuilder:(_)=>const[PopupMenuItem(value:'published',child:Text('نشر')),PopupMenuItem(value:'hidden',child:Text('إخفاء')),PopupMenuItem(value:'removed',child:Text('إزالة'))]);if(resource=='reports')return PopupMenuButton<String>(onSelected:(v)=>action('reports/$id/status',{'status':v}),itemBuilder:(_)=>const[PopupMenuItem(value:'resolved',child:Text('تم الحل')),PopupMenuItem(value:'dismissed',child:Text('رفض البلاغ'))]);if(resource=='categories')return Switch(value:m['active']==true,onChanged:(v)=>action('categories/$id/active',{'active':v}));if(resource=='users')return Switch(value:m['active']==true,onChanged:(v)=>action('users/$id/active',{'active':v}));return null;}}
